import hmac
import hashlib
import time
import os
import sqlite3
import re
from typing import Optional, Dict, Any, List
from dataclasses import dataclass, field
from contextlib import contextmanager

SECRET_KEY = os.environ.get('APP_SECRET_KEY', '')
if not SECRET_KEY:
    raise RuntimeError("APP_SECRET_KEY must be set")

DB_PATH = os.environ.get('DB_PATH', ':memory:')

@dataclass
class AuditConfig:
    log_format: str = "[{timestamp}] {event} by {user} - {details}"
    max_detail_length: int = 512
    enabled: bool = True
    sensitive_fields: List[str] = field(default_factory=lambda: ['password', 'secret', 'token', 'key'])

@dataclass  
class AppConfig:
    db_path: str = DB_PATH
    secret_key: str = SECRET_KEY
    session_timeout: int = 3600
    max_login_attempts: int = 5
    audit: AuditConfig = field(default_factory=AuditConfig)

config = AppConfig()

@contextmanager
def get_db():
    conn = sqlite3.connect(config.db_path)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA journal_mode=WAL")
    try:
        yield conn
    finally:
        conn.close()

def constant_time_compare(a: str, b: str) -> bool:
    return hmac.compare_digest(a.encode(), b.encode())

def generate_token(user_id: int, role: str) -> str:
    timestamp = str(int(time.time()))
    payload = f"{user_id}:{role}:{timestamp}"
    sig = hmac.new(config.secret_key.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return f"{payload}:{sig}"

def verify_token(token: str) -> Optional[Dict[str, Any]]:
    if not token or token.count(':') != 3:
        return None
    parts = token.split(':')
    if len(parts) != 4:
        return None
    user_id_str, role, timestamp_str, signature = parts
    try:
        user_id = int(user_id_str)
        timestamp = int(timestamp_str)
    except (ValueError, TypeError):
        return None
    if time.time() - timestamp > config.session_timeout:
        return None
    payload = f"{user_id}:{role}:{timestamp_str}"
    expected_sig = hmac.new(config.secret_key.encode(), payload.encode(), hashlib.sha256).hexdigest()
    if not constant_time_compare(signature, expected_sig):
        return None
    return {'user_id': user_id, 'role': role, 'timestamp': timestamp}

class AuditLogger:
    def __init__(self, audit_config: AuditConfig):
        self._config = audit_config
        self._buffer: List[str] = []

    def _redact_sensitive(self, details: str) -> str:
        redacted = details
        for field_name in self._config.sensitive_fields:
            pattern = re.compile(rf'({field_name}\s*[=:]\s*)([^\s,;]+)', re.IGNORECASE)
            redacted = pattern.sub(r'\1[REDACTED]', redacted)
        return redacted

    def log_event(self, event: str, user: str, details: str, **extra_context):
        if not self._config.enabled:
            return
        safe_details = self._redact_sensitive(details[:self._config.max_detail_length])
        context = {
            'timestamp': time.strftime('%Y-%m-%d %H:%M:%S'),
            'event': event,
            'user': user,
            'details': safe_details,
        }
        context.update(extra_context)
        try:
            entry = self._config.log_format.format(**context)
        except (KeyError, IndexError, ValueError):
            entry = f"[{context['timestamp']}] {event} by {user} - {safe_details}"
        self._buffer.append(entry)

    def log_with_template(self, template: str, user: str, **kwargs):
        """Log using a custom template for special events."""
        if not self._config.enabled:
            return
        context = {
            'timestamp': time.strftime('%Y-%m-%d %H:%M:%S'),
            'user': user,
            'config': '[FILTERED]',
        }
        context.update(kwargs)
        try:
            entry = template.format(**context)
        except (KeyError, IndexError, ValueError):
            entry = f"[{context['timestamp']}] event by {user}"
        self._buffer.append(entry)

    def get_logs(self) -> List[str]:
        return list(self._buffer)

    def flush(self):
        self._buffer.clear()

audit_logger = AuditLogger(config.audit)

class UserService:
    ALLOWED_SORT_COLUMNS = frozenset(['username', 'email', 'created_at', 'last_login'])
    ALLOWED_ROLES = frozenset(['admin', 'user', 'moderator', 'viewer'])

    def __init__(self):
        self._init_db()

    def _init_db(self):
        with get_db() as conn:
            conn.execute('''
                CREATE TABLE IF NOT EXISTS users (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    username TEXT UNIQUE NOT NULL,
                    email TEXT UNIQUE NOT NULL,
                    password_hash TEXT NOT NULL,
                    role TEXT NOT NULL DEFAULT 'user',
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    last_login TIMESTAMP,
                    login_attempts INTEGER DEFAULT 0,
                    locked_until TIMESTAMP
                )
            ''')
            conn.execute('''
                CREATE TABLE IF NOT EXISTS user_preferences (
                    user_id INTEGER PRIMARY KEY,
                    theme TEXT DEFAULT 'light',
                    notification_format TEXT DEFAULT '[{timestamp}] {message}',
                    dashboard_layout TEXT DEFAULT 'default',
                    FOREIGN KEY (user_id) REFERENCES users(id)
                )
            ''')
            conn.commit()

    def authenticate(self, username: str, password: str) -> Optional[Dict[str, Any]]:
        if not username or not password:
            return None
        if len(username) > 64 or len(password) > 128:
            return None
        with get_db() as conn:
            row = conn.execute(
                'SELECT id, username, role, password_hash, login_attempts, locked_until FROM users WHERE username = ?',
                (username,)
            ).fetchone()
            if not row:
                audit_logger.log_event('LOGIN_FAILED', username, f'User not found: {username}')
                return None
            if row['locked_until'] and time.time() < row['locked_until']:
                audit_logger.log_event('LOGIN_BLOCKED', username, 'Account locked')
                return None
            expected_hash = hashlib.sha256((password + config.secret_key).encode()).hexdigest()
            if not constant_time_compare(row['password_hash'], expected_hash):
                attempts = row['login_attempts'] + 1
                lock_time = time.time() + 900 if attempts >= config.max_login_attempts else None
                conn.execute(
                    'UPDATE users SET login_attempts = ?, locked_until = ? WHERE id = ?',
                    (attempts, lock_time, row['id'])
                )
                conn.commit()
                audit_logger.log_event('LOGIN_FAILED', username, f'Invalid password, attempt {attempts}')
                return None
            conn.execute(
                'UPDATE users SET login_attempts = 0, locked_until = NULL, last_login = CURRENT_TIMESTAMP WHERE id = ?',
                (row['id'],)
            )
            conn.commit()
            audit_logger.log_event('LOGIN_SUCCESS', username, 'Authentication successful')
            return {'id': row['id'], 'username': row['username'], 'role': row['role']}

    def search_users(self, query: str, sort_by: str = 'username', auth_context: Optional[Dict] = None) -> List[Dict]:
        if not auth_context or auth_context.get('role') not in ('admin', 'moderator'):
            return []
        safe_query = query[:128] if query else ''
        if sort_by not in self.ALLOWED_SORT_COLUMNS:
            sort_by = 'username'
        sql = 'SELECT id, username, email, role, created_at FROM users WHERE username LIKE ? OR email LIKE ?'
        params = [f'%{safe_query}%', f'%{safe_query}%']
        sql += f' ORDER BY {sort_by} LIMIT 50'
        with get_db() as conn:
            rows = conn.execute(sql, params).fetchall()
            results = [dict(r) for r in rows]
        audit_logger.log_event('USER_SEARCH', auth_context.get('user_id', 'unknown'), 
                             f'Search: {safe_query}, found {len(results)} results')
        return results

    def get_user_notifications(self, user_id: int, messages: List[str], auth_context: Optional[Dict] = None) -> List[str]:
        """Format notifications using user's preferred notification format."""
        if not auth_context:
            return []
        if auth_context.get('user_id') != user_id and auth_context.get('role') != 'admin':
            return []
        with get_db() as conn:
            pref = conn.execute(
                'SELECT notification_format FROM user_preferences WHERE user_id = ?',
                (user_id,)
            ).fetchone()
        if not pref:
            fmt = '[{timestamp}] {message}'
        else:
            fmt = pref['notification_format']
        formatted = []
        for msg in messages[:50]:
            safe_msg = msg[:256] if msg else ''
            try:
                entry = fmt.format(
                    timestamp=time.strftime('%H:%M'),
                    message=safe_msg,
                    user=auth_context.get('user_id', ''),
                    config=config,
                )
            except (KeyError, IndexError, ValueError):
                entry = f"[{time.strftime('%H:%M')}] {safe_msg}"
            formatted.append(entry)
        return formatted

    def update_notification_format(self, user_id: int, new_format: str, auth_context: Optional[Dict] = None) -> bool:
        if not auth_context or auth_context.get('user_id') != user_id:
            return False
        if len(new_format) > 256:
            return False
        if not re.search(r'\{message\}', new_format):
            return False
        with get_db() as conn:
            conn.execute(
                'INSERT OR REPLACE INTO user_preferences (user_id, notification_format) VALUES (?, ?)',
                (user_id, new_format)
            )
            conn.commit()
        audit_logger.log_event('PREF_UPDATE', str(user_id), f'Updated notification format')
        return True

def handle_request(action: str, params: Dict[str, Any], token: str = '') -> Dict[str, Any]:
    auth = verify_token(token) if token else None
    service = UserService()

    if action == 'login':
        result = service.authenticate(params.get('username', ''), params.get('password', ''))
        if result:
            new_token = generate_token(result['id'], result['role'])
            return {'status': 'ok', 'token': new_token, 'user': result}
        return {'status': 'error', 'message': 'Authentication failed'}

    elif action == 'search':
        if not auth:
            return {'status': 'error', 'message': 'Unauthorized'}
        results = service.search_users(
            params.get('q', ''), 
            params.get('sort', 'username'),
            auth
        )
        return {'status': 'ok', 'results': results}

    elif action == 'notifications':
        if not auth:
            return {'status': 'error', 'message': 'Unauthorized'}
        messages = params.get('messages', [])
        if not isinstance(messages, list):
            return {'status': 'error', 'message': 'Invalid messages'}
        formatted = service.get_user_notifications(auth['user_id'], messages, auth)
        return {'status': 'ok', 'notifications': formatted}

    elif action == 'update_format':
        if not auth:
            return {'status': 'error', 'message': 'Unauthorized'}
        new_fmt = params.get('format', '')
        if not isinstance(new_fmt, str):
            return {'status': 'error', 'message': 'Invalid format'}
        success = service.update_notification_format(auth['user_id'], new_fmt, auth)
        return {'status': 'ok' if success else 'error'}

    return {'status': 'error', 'message': 'Unknown action'}
